+package figlet
+
+import (
+	"archive/zip"
+	"bytes"
+	"fmt"
+	"io"
+	"os"
+	"path/filepath"
+	"strings"
+	"unicode/utf8"
+)
+
+var mandatoryExtraCodes = []int{196, 214, 220, 228, 246, 252, 223}
+
+type Glyph struct {
+	Lines []string
+	Width int
+}
+
+type Font struct {
+	Hardblank      rune
+	Height         int
+	OldLayout      int
+	PrintDirection int
+	FullLayout     int
+	Glyphs         map[int]Glyph
+}
+
+func loadFont(fontDir, name string) (*Font, error) {
+	data, err := readNamedResource(fontDir, name, []string{".flf", ".tlf"})
+	if err != nil {
+		return nil, err
+	}
+	if extracted, ok := maybeUnzip(data); ok {
+		data = extracted
+	}
+	return parseFont(data)
+}
+
+func readNamedResource(baseDir, name string, exts []string) ([]byte, error) {
+	name = stripKnownExtension(name, exts)
+	candidates := make([]string, 0, len(exts)*2)
+	if strings.ContainsRune(name, os.PathSeparator) {
+		for _, ext := range exts {
+			candidates = append(candidates, name+ext)
+		}
+	} else {
+		for _, ext := range exts {
+			candidates = append(candidates, filepath.Join(baseDir, name+ext))
+		}
+		for _, ext := range exts {
+			candidates = append(candidates, name+ext)
+		}
+	}
+
+	for _, candidate := range candidates {
+		data, err := os.ReadFile(candidate)
+		if err == nil {
+			return data, nil
+		}
+	}
+	return nil, fmt.Errorf("%s", name)
+}
+
+func maybeUnzip(data []byte) ([]byte, bool) {
+	reader, err := zip.NewReader(bytes.NewReader(data), int64(len(data)))
+	if err != nil || len(reader.File) == 0 {
+		return nil, false
+	}
+	rc, err := reader.File[0].Open()
+	if err != nil {
+		return nil, false
+	}
+	defer rc.Close()
+	out, err := io.ReadAll(rc)
+	if err != nil {
+		return nil, false
+	}
+	return out, true
+}
+
+func parseFont(data []byte) (*Font, error) {
+	lines := splitTextLines(data)
+	if len(lines) == 0 {
+		return nil, fmt.Errorf("invalid font")
+	}
+
+	header := lines[0]
+	if len(header) < 6 || (!strings.HasPrefix(header, "flf2a") && !strings.HasPrefix(header, "tlf2a")) {
+		return nil, fmt.Errorf("invalid font")
+	}
+
+	hardblank, _ := utf8.DecodeRuneInString(header[5:])
+	fields := strings.Fields(header[6:])
+	if len(fields) < 5 {
+		return nil, fmt.Errorf("invalid font")
+	}
+
+	height := atoiLikeC(fields[0])
+	oldLayout := atoiLikeC(fields[3])
+	commentLines := atoiLikeC(fields[4])
+	printDir := 0
+	if len(fields) > 5 {
+		printDir = atoiLikeC(fields[5])
+	}
+	fullLayout := 0
+	if len(fields) > 6 {
+		fullLayout = atoiLikeC(fields[6])
+	}
+
+	font := &Font{
+		Hardblank:      hardblank,
+		Height:         height,
+		OldLayout:      oldLayout,
+		PrintDirection: printDir,
+		FullLayout:     fullLayout,
+		Glyphs:         make(map[int]Glyph),
+	}
+
+	index := 1 + commentLines
+	for code := 32; code <= 126; code++ {
+		glyph, next, err := readGlyph(lines, index, height)
+		if err != nil {
+			return nil, err
+		}
+		font.Glyphs[code] = glyph
+		index = next
+	}
+	for _, code := range mandatoryExtraCodes {
+		glyph, next, err := readGlyph(lines, index, height)
+		if err != nil {
+			return nil, err
+		}
+		font.Glyphs[code] = glyph
+		index = next
+	}
+
+	for index < len(lines) {
+		tagLine := strings.TrimSpace(lines[index])
+		index++
+		if tagLine == "" {
+			continue
+		}
+		fields := strings.Fields(tagLine)
+		if len(fields) == 0 {
+			continue
+		}
+		code, ok := parseIntAuto(fields[0])
+		if !ok {
+			continue
+		}
+		glyph, next, err := readGlyph(lines, index, height)
+		if err != nil {
+			return nil, err
+		}
+		font.Glyphs[code] = glyph
+		index = next
+	}
+
+	return font, nil
+}
+
+func splitTextLines(data []byte) []string {
+	parts := strings.Split(string(data), "\n")
+	for i := range parts {
+		parts[i] = strings.TrimSuffix(parts[i], "\r")
+	}
+	if len(parts) > 0 && parts[len(parts)-1] == "" {
+		parts = parts[:len(parts)-1]
+	}
+	return parts
+}
+
+func readGlyph(lines []string, start, height int) (Glyph, int, error) {
+	if start+height > len(lines) {
+		return Glyph{}, start, fmt.Errorf("invalid font")
+	}
+	glyphLines := make([]string, height)
+	width := 0
+	for i := 0; i < height; i++ {
+		line := stripEndmark(lines[start+i])
+		glyphLines[i] = line
+		if w := utf8.RuneCountInString(line); w > width {
+			width = w
+		}
+	}
+	return Glyph{Lines: glyphLines, Width: width}, start + height, nil
+}
+
+func stripEndmark(line string) string {
+	runes := []rune(line)
+	for len(runes) > 0 {
+		last := runes[len(runes)-1]
+		if last == '@' || last == '#' || last == '$' || last == '\u007f' {
+			runes = runes[:len(runes)-1]
+			continue
+		}
+		break
+	}
+	return string(runes)
+}
+
+func (f *Font) GlyphForRune(r rune) (Glyph, bool) {
+	if r == '\t' || r == '\r' || r == '\v' || r == '\f' {
+		r = ' '
+	}
+	glyph, ok := f.Glyphs[int(r)]
+	return glyph, ok
+}
