package figlet

import (
	"fmt"
	"strings"
	"unicode/utf8"
)

type Controls struct {
	UTF8        bool
	Translations []map[rune]rune
}

func loadControls(fontDir string, names []string, german bool) (*Controls, error) {
	ctrl := &Controls{}
	for _, name := range names {
		data, err := readNamedResource(fontDir, name, []string{".flc"})
		if err != nil {
			return nil, err
		}
		if extracted, ok := maybeUnzip(data); ok {
			data = extracted
		}
		fileCtrl, err := parseControlFile(data)
		if err != nil {
			return nil, fmt.Errorf("%s", name)
		}
		if fileCtrl.UTF8 {
			ctrl.UTF8 = true
		}
		ctrl.Translations = append(ctrl.Translations, fileCtrl.Translations...)
	}
	if german {
		ctrl.Translations = append(ctrl.Translations, germanMap())
	}
	return ctrl, nil
}

func parseControlFile(data []byte) (*Controls, error) {
	lines := splitTextLines(data)
	if len(lines) == 0 || strings.TrimSpace(lines[0]) != "flc2a" {
		return nil, fmt.Errorf("invalid control file")
	}
	ctrl := &Controls{}
	for _, raw := range lines[1:] {
		line := strings.TrimSpace(raw)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if line == "u" {
			ctrl.UTF8 = true
			continue
		}
		if line == "h" || line == "f" {
			continue
		}
		if strings.HasPrefix(line, "g ") {
			continue
		}

		fields := strings.Fields(line)
		if len(fields) < 2 {
			continue
		}
		if fields[0] == "t" {
			fields = fields[1:]
		}
		if len(fields) < 2 {
			continue
		}

		translation := make(map[rune]rune)
		from := expandPattern(fields[0])
		to := expandPattern(fields[1])
		if len(from) == 0 || len(to) == 0 {
			continue
		}
		last := to[len(to)-1]
		for i, src := range from {
			dst := last
			if i < len(to) {
				dst = to[i]
			}
			translation[src] = dst
		}
		ctrl.Translations = append(ctrl.Translations, translation)
	}
	return ctrl, nil
}

func germanMap() map[rune]rune {
	return map[rune]rune{
		'[': 'Ä',
		'\\': 'Ö',
		']': 'Ü',
		'{': 'ä',
		'|': 'ö',
		'}': 'ü',
		'~': 'ß',
	}
}

func expandPattern(token string) []rune {
	var out []rune
	for i := 0; i < len(token); {
		left, next := parsePatternItem(token, i)
		if next < len(token) && token[next] == '-' {
			right, after := parsePatternItem(token, next+1)
			if left != 0 && right != 0 {
				step := 1
				if right < left {
					step = -1
				}
				for r := left; ; r += rune(step) {
					out = append(out, r)
					if r == right {
						break
					}
				}
				i = after
				continue
			}
		}
		if left != 0 {
			out = append(out, left)
		}
		if next <= i {
			break
		}
		i = next
	}
	return out
}

func parsePatternItem(token string, start int) (rune, int) {
	if start >= len(token) {
		return 0, start
	}
	if strings.HasPrefix(token[start:], "0x") || strings.HasPrefix(token[start:], "0X") {
		end := start + 2
		for end < len(token) && isHex(token[end]) {
			end++
		}
		if end > start+2 {
			if n, ok := parseIntAuto(token[start:end]); ok {
				return rune(n), end
			}
		}
	}
	if token[start] == '\\' {
		if start+1 >= len(token) {
			return '\\', start + 1
		}
		switch {
		case strings.HasPrefix(token[start+1:], "0x") || strings.HasPrefix(token[start+1:], "0X"):
			end := start + 3
			for end < len(token) && isHex(token[end]) {
				end++
			}
			if n, ok := parseIntAuto(token[start+1 : end]); ok {
				return rune(n), end
			}
		case token[start+1] == '-':
			end := start + 2
			for end < len(token) && token[end] >= '0' && token[end] <= '9' {
				end++
			}
			if n, ok := parseIntAuto(token[start+2 : end]); ok {
				return rune(n), end
			}
		case token[start+1] >= '0' && token[start+1] <= '9':
			end := start + 1
			for end < len(token) && token[end] >= '0' && token[end] <= '9' {
				end++
			}
			if n, ok := parseIntAuto(token[start+1 : end]); ok {
				return rune(n), end
			}
		default:
			r, size := utf8.DecodeRuneInString(token[start+1:])
			return r, start + 1 + size
		}
	}
	r, size := utf8.DecodeRuneInString(token[start:])
	return r, start + size
}

func isHex(b byte) bool {
	return (b >= '0' && b <= '9') || (b >= 'a' && b <= 'f') || (b >= 'A' && b <= 'F')
}

func (c *Controls) Decode(line []byte) []rune {
	var runes []rune
	if c != nil && c.UTF8 {
		for len(line) > 0 {
			r, size := utf8.DecodeRune(line)
			if r == utf8.RuneError && size == 1 {
				runes = append(runes, rune(line[0]))
				line = line[1:]
				continue
			}
			runes = append(runes, r)
			line = line[size:]
		}
	} else {
		runes = make([]rune, 0, len(line))
		for _, b := range line {
			runes = append(runes, rune(b))
		}
	}

	if c == nil {
		return runes
	}
	for _, table := range c.Translations {
		for i, r := range runes {
			if mapped, ok := table[r]; ok {
				runes[i] = mapped
			}
		}
	}
	return runes
}

/workspace/internal/figlet/app.go.content:
package figlet

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"unsafe"
)

const (
	defaultFontDir  = "/usr/local/share/figlet"
	defaultFontName = "standard"
	defaultWidth    = 80
	versionNumber   = "20205"
	supportedFonts  = "flf2 tlf2"
)

type justifyMode int

const (
	justifyAuto justifyMode = iota
	justifyLeft
	justifyCenter
	justifyRight
)

type directionMode int

const (
	directionAuto directionMode = iota
	directionLeft
	directionRight
)

type layoutChoiceKind int

const (
	layoutDefault layoutChoiceKind = iota
	layoutForceSmush
	layoutKerning
	layoutFullWidth
	layoutOverlap
	layoutExplicit
)

type layoutChoice struct {
	kind  layoutChoiceKind
	value int
}

type config struct {
	FontDir      string
	FontName     string
	OutputWidth  int
	Justify      justifyMode
	Direction    directionMode
	Paragraph    bool
	German       bool
	InfoCode     int
	Controls     []string
	LayoutChoice layoutChoice
}

func defaultConfig() config {
	return config{
		FontDir:      defaultFontDir,
		FontName:     defaultFontName,
		OutputWidth:  defaultWidth,
		Justify:      justifyAuto,
		Direction:    directionAuto,
		InfoCode:     -1,
		LayoutChoice: layoutChoice{kind: layoutDefault},
	}
}

func Run(argv []string, stdin io.Reader, stdout, stderr io.Writer) int {
	cfg, messageArgs, parseErr := parseArgs(argv, stdout)
	if parseErr != nil {
		fmt.Fprint(stderr, parseErr.Error())
		return 1
	}

	if cfg.InfoCode >= 0 {
		return printInfo(argv[0], cfg, stdout)
	}

	controls, err := loadControls(cfg.FontDir, cfg.Controls, cfg.German)
	if err != nil {
		fmt.Fprintf(stderr, "%s: %s: Unable to open control file\n", filepath.Base(argv[0]), err.Error())
		return 1
	}

	font, err := loadFont(cfg.FontDir, cfg.FontName)
	if err != nil {
		fmt.Fprintf(stderr, "%s: %s: Unable to open font file\n", filepath.Base(argv[0]), err.Error())
		return 1
	}

	var rawInput []byte
	if len(messageArgs) > 0 {
		rawInput = joinMessageArgs(messageArgs)
	} else {
		var readErr error
		rawInput, readErr = io.ReadAll(stdin)
		if readErr != nil {
			fmt.Fprintf(stderr, "%s: %v\n", filepath.Base(argv[0]), readErr)
			return 1
		}
	}

	if cfg.Paragraph {
		rawInput = paragraphize(rawInput)
	}

	logicalLines := splitLogicalLines(rawInput)
	layout := resolveLayout(font, cfg.LayoutChoice)
	direction := resolveDirection(font, cfg.Direction)
	justify := resolveJustification(direction, cfg.Justify)

	blocks := renderInput(font, controls, logicalLines, layout, direction, cfg.OutputWidth)
	for _, block := range blocks {
		for _, line := range justifyBlock(block, cfg.OutputWidth, justify, font.Hardblank) {
			if _, err := io.WriteString(stdout, line); err != nil {
				return 1
			}
			if _, err := io.WriteString(stdout, "\n"); err != nil {
				return 1
			}
		}
	}

	return 0
}

func parseArgs(argv []string, stdout io.Writer) (config, []string, error) {
	cfg := defaultConfig()
	args := argv[1:]

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if len(arg) < 2 || arg[0] != '-' {
			return cfg, args[i:], nil
		}

		for j := 1; j < len(arg); j++ {
			opt := arg[j]
			switch opt {
			case 'c':
				cfg.Justify = justifyCenter
			case 'l':
				cfg.Justify = justifyLeft
			case 'r':
				cfg.Justify = justifyRight
			case 'x':
				cfg.Justify = justifyAuto
			case 'L':
				cfg.Direction = directionLeft
			case 'R':
				cfg.Direction = directionRight
			case 'X':
				cfg.Direction = directionAuto
			case 'n':
				cfg.Paragraph = false
			case 'p':
				cfg.Paragraph = true
			case 'D':
				cfg.German = true
			case 'E':
				cfg.German = false
			case 'N':
				cfg.Controls = nil
			case 's':
				cfg.LayoutChoice = layoutChoice{kind: layoutDefault}
			case 'S':
				cfg.LayoutChoice = layoutChoice{kind: layoutForceSmush}
			case 'k':
				cfg.LayoutChoice = layoutChoice{kind: layoutKerning}
			case 'W':
				cfg.LayoutChoice = layoutChoice{kind: layoutFullWidth}
			case 'o':
				cfg.LayoutChoice = layoutChoice{kind: layoutOverlap}
			case 't':
				if width := terminalWidth(stdout); width > 0 {
					cfg.OutputWidth = width
				}
			case 'v':
				cfg.InfoCode = 0
			case 'd', 'f', 'm', 'w', 'C', 'I':
				value := ""
				if j+1 < len(arg) {
					value = arg[j+1:]
					j = len(arg)
				} else {
					i++
					if i >= len(args) {
						return cfg, nil, usageError(argv[0], fmt.Sprintf("option requires an argument -- '%c'", opt))
					}
					value = args[i]
				}
				switch opt {
				case 'd':
					cfg.FontDir = value
				case 'f':
					cfg.FontName = stripKnownExtension(value, []string{".flf", ".tlf"})
				case 'm':
					cfg.LayoutChoice = layoutChoice{kind: layoutExplicit, value: atoiLikeC(value)}
				case 'w':
					if width := atoiLikeC(value); width > 0 {
						cfg.OutputWidth = width
					}
				case 'C':
					cfg.Controls = append(cfg.Controls, stripKnownExtension(value, []string{".flc"}))
				case 'I':
					cfg.InfoCode = atoiLikeC(value)
				}
			default:
				return cfg, nil, usageError(argv[0], fmt.Sprintf("invalid option -- '%c'", opt))
			}
		}
	}

	return cfg, nil, nil
}

func usageError(rawProgram, message string) error {
	return fmt.Errorf("%s: %s\n%s", rawProgram, message, usageText(filepath.Base(rawProgram)))
}

func usageText(program string) string {
	return fmt.Sprintf(
		"Usage: %s [ -cklnoprstvxDELNRSWX ] [ -d fontdirectory ]\n              [ -f fontfile ] [ -m smushmode ] [ -w outputwidth ]\n              [ -C controlfile ] [ -I infocode ] [ message ]\n",
		program,
	)
}

func printInfo(program string, cfg config, stdout io.Writer) int {
	switch {
	case cfg.InfoCode < 0:
		return 0
	case cfg.InfoCode == 0:
		fmt.Fprintf(stdout,
			"FIGlet Copyright (C) 1991-2012 Glenn Chappell, Ian Chai, John Cowan,\nChristiaan Keet and Claudio Matsuoka\nInternet: <info@figlet.org> Version: 2.2.5, date: 31 May 2012\n\nFIGlet, along with the various FIGlet fonts and documentation, may be\nfreely copied and distributed.\n\nIf you use FIGlet, please send an e-mail message to <info@figlet.org>.\n\nThe latest version of FIGlet is available from the web site,\n\thttp://www.figlet.org/\n\n%s",
			usageText(filepath.Base(program)),
		)
	case cfg.InfoCode == 1:
		fmt.Fprintln(stdout, versionNumber)
	case cfg.InfoCode == 2:
		fmt.Fprintln(stdout, cfg.FontDir)
	case cfg.InfoCode == 3:
		fmt.Fprintln(stdout, cfg.FontName)
	case cfg.InfoCode == 4:
		fmt.Fprintln(stdout, cfg.OutputWidth)
	case cfg.InfoCode == 5:
		fmt.Fprintln(stdout, supportedFonts)
	default:
	}
	return 0
}

func joinMessageArgs(args []string) []byte {
	lines := make([][]byte, 0, len(args)+1)
	current := make([]byte, 0)
	atLineStart := true
	for _, arg := range args {
		if !atLineStart {
			current = append(current, ' ')
		}
		current = append(current, []byte(arg)...)
		atLineStart = false
		if arg == "" {
			lines = append(lines, append([]byte(nil), current...))
			current = current[:0]
			atLineStart = true
		}
	}
	if len(current) > 0 || len(args) == 0 || args[len(args)-1] != "" {
		lines = append(lines, append([]byte(nil), current...))
	}
	return []byte(strings.Join(byteSlicesToStrings(lines), "\n"))
}

func byteSlicesToStrings(lines [][]byte) []string {
	out := make([]string, 0, len(lines))
	for _, line := range lines {
		out = append(out, string(line))
	}
	return out
}

func splitLogicalLines(input []byte) [][]byte {
	if len(input) == 0 {
		return nil
	}
	parts := bytesSplit(input, '\n')
	if len(parts) > 0 && len(parts[len(parts)-1]) == 0 && input[len(input)-1] == '\n' {
		parts = parts[:len(parts)-1]
	}
	return parts
}

func paragraphize(input []byte) []byte {
	if len(input) == 0 {
		return nil
	}
	out := append([]byte(nil), input...)
	for i := 0; i < len(out); i++ {
		if out[i] != '\n' {
			continue
		}
		prevNL := i > 0 && out[i-1] == '\n'
		nextSpace := i+1 < len(out) && out[i+1] == ' '
		if !prevNL && !nextSpace {
			out[i] = ' '
		}
	}
	return out
}

func bytesSplit(input []byte, sep byte) [][]byte {
	start := 0
	out := make([][]byte, 0, 8)
	for i, b := range input {
		if b != sep {
			continue
		}
		out = append(out, append([]byte(nil), input[start:i]...))
		start = i + 1
	}
	out = append(out, append([]byte(nil), input[start:]...))
	return out
}

func stripKnownExtension(name string, exts []string) string {
	for _, ext := range exts {
		if strings.HasSuffix(name, ext) {
			return strings.TrimSuffix(name, ext)
		}
	}
	return name
}

func atoiLikeC(value string) int {
	sign := 1
	i := 0
	for i < len(value) && (value[i] == ' ' || value[i] == '\t' || value[i] == '\n' || value[i] == '\r' || value[i] == '\f' || value[i] == '\v') {
		i++
	}
	if i < len(value) && (value[i] == '+' || value[i] == '-') {
		if value[i] == '-' {
			sign = -1
		}
		i++
	}
	n := 0
	started := false
	for i < len(value) && value[i] >= '0' && value[i] <= '9' {
		started = true
		n = n*10 + int(value[i]-'0')
		i++
	}
	if !started {
		return 0
	}
	return sign * n
}

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func terminalWidth(stdout io.Writer) int {
	file, ok := stdout.(*os.File)
	if !ok {
		return 0
	}
	ws := winsize{}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, file.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if errno != 0 || ws.Col == 0 {
		return 0
	}
	return int(ws.Col)
}

func resolveDirection(font *Font, mode directionMode) directionMode {
	switch mode {
	case directionLeft, directionRight:
		return mode
	default:
		if font.PrintDirection == 1 {
			return directionRight
		}
		return directionLeft
	}
}

func resolveJustification(direction directionMode, mode justifyMode) justifyMode {
	if mode != justifyAuto {
		return mode
	}
	if direction == directionRight {
		return justifyRight
	}
	return justifyLeft
}

type effectiveLayout struct {
	Kind       layoutChoiceKind
	SmushRules int
	Universal  bool
}

func resolveLayout(font *Font, choice layoutChoice) effectiveLayout {
	switch choice.kind {
	case layoutFullWidth:
		return effectiveLayout{Kind: layoutFullWidth}
	case layoutKerning:
		return effectiveLayout{Kind: layoutKerning}
	case layoutOverlap:
		return effectiveLayout{Kind: layoutOverlap}
	case layoutForceSmush:
		return fullLayoutToEffective(font.FullLayout)
	case layoutExplicit:
		switch choice.value {
		case -2:
			return defaultLayoutForFont(font)
		case -1:
			return effectiveLayout{Kind: layoutFullWidth}
		case 0:
			return effectiveLayout{Kind: layoutKerning}
		default:
			return explicitLayoutToEffective(choice.value)
		}
	default:
		return defaultLayoutForFont(font)
	}
}

func defaultLayoutForFont(font *Font) effectiveLayout {
	switch {
	case font.OldLayout < 0:
		return effectiveLayout{Kind: layoutFullWidth}
	case font.OldLayout == 0:
		return effectiveLayout{Kind: layoutKerning}
	default:
		return effectiveLayout{Kind: layoutForceSmush, SmushRules: font.OldLayout}
	}
}

func fullLayoutToEffective(layout int) effectiveLayout {
	if layout&64 != 0 {
		rules := layout & 63
		if rules == 0 {
			return effectiveLayout{Kind: layoutForceSmush, Universal: true}
		}
		return effectiveLayout{Kind: layoutForceSmush, SmushRules: rules}
	}
	if layout > 0 {
		return effectiveLayout{Kind: layoutForceSmush, SmushRules: layout & 63}
	}
	return effectiveLayout{Kind: layoutOverlap}
}

func explicitLayoutToEffective(layout int) effectiveLayout {
	if layout&64 != 0 {
		rules := layout & 63
		if rules == 0 {
			return effectiveLayout{Kind: layoutForceSmush, Universal: true}
		}
		return effectiveLayout{Kind: layoutForceSmush, SmushRules: rules}
	}
	return effectiveLayout{Kind: layoutForceSmush, SmushRules: layout & 63}
}

func parseIntAuto(value string) (int, bool) {
	n, err := strconv.ParseInt(value, 0, 32)
	if err != nil {
		return 0, false
	}
	return int(n), true
}

