package figlet

import (
	"strings"
	"unicode/utf8"
)

type renderedBlock struct {
	Lines []string
	Width int
}

func renderInput(font *Font, controls *Controls, rawLines [][]byte, layout effectiveLayout, direction directionMode, outputWidth int) []renderedBlock {
	if len(rawLines) == 0 {
		return nil
	}
	blocks := make([]renderedBlock, 0, len(rawLines))
	for _, raw := range rawLines {
		decoded := controls.Decode(raw)
		if direction == directionRight {
			reverseRunes(decoded)
		}
		lineBlocks := renderLine(font, decoded, layout, outputWidth)
		blocks = append(blocks, lineBlocks...)
	}
	return blocks
}

func renderLine(font *Font, input []rune, layout effectiveLayout, outputWidth int) []renderedBlock {
	if len(input) == 0 {
		return []renderedBlock{{Lines: make([]string, font.Height), Width: 0}}
	}
	if outputWidth == 1 {
		return renderWidthOne(font, input)
	}

	var blocks []renderedBlock
	current := blankCanvas(font.Height)
	currentWidth := 0
	sawGlyph := false

	for _, r := range input {
		glyph, ok := font.GlyphForRune(r)
		if !ok {
			continue
		}
		sawGlyph = true

		candidate, candWidth := mergeGlyph(current, currentWidth, glyph, layout, font.Hardblank)
		if outputWidth > 1 && candWidth >= outputWidth {
			if currentWidth > 0 {
				blocks = append(blocks, finalizeBlock(current, currentWidth, font.Hardblank))
				current = blankCanvas(font.Height)
				currentWidth = 0
				if r == ' ' {
					continue
				}
				candidate, candWidth = mergeGlyph(current, currentWidth, glyph, layout, font.Hardblank)
			}
			if candWidth >= outputWidth {
				trunc := outputWidth - 1
				if trunc < 0 {
					trunc = 0
				}
				blocks = append(blocks, finalizeBlock(truncateCanvas(candidate, trunc), trunc, font.Hardblank))
				current = blankCanvas(font.Height)
				currentWidth = 0
				continue
			}
		}

		current = candidate
		currentWidth = candWidth
	}

	if !sawGlyph {
		return nil
	}
	if currentWidth > 0 {
		blocks = append(blocks, finalizeBlock(current, currentWidth, font.Hardblank))
	}
	return blocks
}

func renderWidthOne(font *Font, input []rune) []renderedBlock {
	blocks := make([]renderedBlock, 0, len(input))
	startOfLine := true
	for _, r := range input {
		if r == ' ' {
			if startOfLine {
				if glyph, ok := font.GlyphForRune(' '); ok {
					canvas := glyphToCanvas(glyph)
					blocks = append(blocks, finalizeBlock(canvas, glyph.Width, font.Hardblank))
				}
			}
			continue
		}
		glyph, ok := font.GlyphForRune(r)
		if !ok {
			continue
		}
		canvas := glyphToCanvas(glyph)
		blocks = append(blocks, finalizeBlock(canvas, glyph.Width, font.Hardblank))
		startOfLine = false
	}
	return blocks
}

func blankCanvas(height int) [][]rune {
	canvas := make([][]rune, height)
	for i := range canvas {
		canvas[i] = []rune{}
	}
	return canvas
}

func glyphToCanvas(g Glyph) [][]rune {
	canvas := make([][]rune, len(g.Lines))
	for i, line := range g.Lines {
		row := []rune(line)
		if len(row) < g.Width {
			row = append(row, make([]rune, g.Width-len(row))...)
		}
		for j := range row {
			if row[j] == 0 {
				row[j] = ' '
			}
		}
		canvas[i] = row
	}
	return canvas
}

func mergeGlyph(current [][]rune, currentWidth int, glyph Glyph, layout effectiveLayout, hardblank rune) ([][]rune, int) {
	next := glyphToCanvas(glyph)
	nextWidth := glyph.Width
	if currentWidth == 0 {
		return next, nextWidth
	}

	if layout.Kind == layoutOverlap && nextWidth > 1 {
		for i := range next {
			next[i] = next[i][1:]
		}
		nextWidth--
	}

	overlap := 0
	switch layout.Kind {
	case layoutFullWidth:
		overlap = 0
	case layoutKerning, layoutOverlap:
		overlap = maxKerningOverlap(current, currentWidth, next, nextWidth)
	default:
		overlap = maxSmushOverlap(current, currentWidth, next, nextWidth, layout, hardblank)
	}
	return combineCanvases(current, currentWidth, next, nextWidth, overlap, layout, hardblank)
}

func maxKerningOverlap(current [][]rune, currentWidth int, next [][]rune, nextWidth int) int {
	max := minInt(currentWidth, nextWidth)
	for overlap := max; overlap >= 0; overlap-- {
		if overlapFits(current, currentWidth, next, nextWidth, overlap, effectiveLayout{Kind: layoutKerning}, 0) {
			return overlap
		}
	}
	return 0
}

func maxSmushOverlap(current [][]rune, currentWidth int, next [][]rune, nextWidth int, layout effectiveLayout, hardblank rune) int {
	max := minInt(currentWidth, nextWidth)
	for overlap := max; overlap >= 0; overlap-- {
		if overlapFits(current, currentWidth, next, nextWidth, overlap, layout, hardblank) {
			return overlap
		}
	}
	return 0
}

func overlapFits(current [][]rune, currentWidth int, next [][]rune, nextWidth int, overlap int, layout effectiveLayout, hardblank rune) bool {
	for row := range current {
		for i := 0; i < overlap; i++ {
			left := currentCell(current, row, currentWidth-overlap+i)
			right := currentCell(next, row, i)
			if left == ' ' || right == ' ' {
				continue
			}
			if layout.Kind == layoutKerning || layout.Kind == layoutOverlap {
				return false
			}
			if layout.Universal {
				continue
			}
			if _, ok := smushChars(left, right, layout.SmushRules, hardblank); ok {
				continue
			}
			return false
		}
	}
	return true
}

func combineCanvases(current [][]rune, currentWidth int, next [][]rune, nextWidth int, overlap int, layout effectiveLayout, hardblank rune) ([][]rune, int) {
	newWidth := currentWidth + nextWidth - overlap
	out := make([][]rune, len(current))
	for row := range current {
		out[row] = make([]rune, newWidth)
		for i := range out[row] {
			out[row][i] = ' '
		}
		for i := 0; i < currentWidth; i++ {
			out[row][i] = currentCell(current, row, i)
		}
		for i := 0; i < nextWidth; i++ {
			pos := currentWidth - overlap + i
			right := currentCell(next, row, i)
			left := out[row][pos]
			switch {
			case right == ' ':
			case left == ' ':
				out[row][pos] = right
			case layout.Kind == layoutKerning || layout.Kind == layoutOverlap:
				out[row][pos] = right
			case layout.Universal:
				out[row][pos] = right
			default:
				if smushed, ok := smushChars(left, right, layout.SmushRules, hardblank); ok {
					out[row][pos] = smushed
				} else {
					out[row][pos] = right
				}
			}
		}
	}
	return out, newWidth
}

func currentCell(canvas [][]rune, row, col int) rune {
	if row >= len(canvas) || col < 0 || col >= len(canvas[row]) {
		return ' '
	}
	return canvas[row][col]
}

func smushChars(left, right rune, rules int, hardblank rune) (rune, bool) {
	if left == hardblank && right == hardblank {
		if rules&32 != 0 {
			return hardblank, true
		}
		return 0, false
	}
	if left == hardblank || right == hardblank {
		return 0, false
	}
	if rules&1 != 0 && left == right {
		return left, true
	}
	if rules&2 != 0 {
		if left == '_' && isHierarchyRune(right) {
			return right, true
		}
		if right == '_' && isHierarchyRune(left) {
			return left, true
		}
	}
	if rules&4 != 0 {
		if rankLeft, okLeft := hierarchyRank(left); okLeft {
			if rankRight, okRight := hierarchyRank(right); okRight && rankLeft != rankRight {
				if rankLeft > rankRight {
					return left, true
				}
				return right, true
			}
		}
	}
	if rules&8 != 0 {
		if (left == '[' && right == ']') || (left == ']' && right == '[') ||
			(left == '{' && right == '}') || (left == '}' && right == '{') ||
			(left == '(' && right == ')') || (left == ')' && right == '(') {
			return '|', true
		}
	}
	if rules&16 != 0 {
		switch {
		case left == '/' && right == '\\':
			return '|', true
		case left == '\\' && right == '/':
			return 'Y', true
		case left == '>' && right == '<':
			return 'X', true
		}
	}
	return 0, false
}

func isHierarchyRune(r rune) bool {
	_, ok := hierarchyRank(r)
	return ok
}

func hierarchyRank(r rune) (int, bool) {
	switch r {
	case '|':
		return 1, true
	case '/', '\\':
		return 2, true
	case '[', ']':
		return 3, true
	case '{', '}':
		return 4, true
	case '(', ')':
		return 5, true
	case '<', '>':
		return 6, true
	default:
		return 0, false
	}
}

func finalizeBlock(canvas [][]rune, width int, hardblank rune) renderedBlock {
	lines := make([]string, len(canvas))
	for i, row := range canvas {
		if width < len(row) {
			row = row[:width]
		}
