func truncateCanvas(canvas [][]rune, width int) [][]rune {
	out := make([][]rune, len(canvas))
	for i, row := range canvas {
		if width > len(row) {
			width = len(row)
		}
		out[i] = append([]rune(nil), row[:width]...)
	}
	return out
}

func justifyBlock(block renderedBlock, outputWidth int, justify justifyMode, hardblank rune) []string {
	lines := make([]string, len(block.Lines))
	for i, line := range block.Lines {
		pad := 0
		if outputWidth > block.Width {
			switch justify {
			case justifyRight:
				pad = outputWidth - block.Width
			case justifyCenter:
				pad = (outputWidth - block.Width) / 2
			}
		}
		if pad > 0 {
			lines[i] = strings.Repeat(" ", pad) + line
		} else {
			lines[i] = line
		}
	}
	return lines
}

func reverseRunes(runes []rune) {
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func lineWidth(line string) int {
	return utf8.RuneCountInString(line)
}

