package figlet

import (
	"bytes"
	"testing"
)

func TestRunStandardHello(t *testing.T) {
	var stdout, stderr bytes.Buffer
	code := Run([]string{"executable", "-d", "../../fonts", "Hello"}, bytes.NewReader(nil), &stdout, &stderr)
	if code != 0 {
		t.Fatalf("exit=%d stderr=%q", code, stderr.String())
	}
	want := "" +
		" _   _      _ _       \n" +
		"| | | | ___| | | ___  \n" +
		"| |_| |/ _ \\ | |/ _ \\ \n" +
		"|  _  |  __/ | | (_) |\n" +
		"|_| |_|\\___|_|_|\\___/ \n" +
		"                      \n"
	if stdout.String() != want {
		t.Fatalf("stdout mismatch\nwant:\n%q\ngot:\n%q", want, stdout.String())
	}
}

