package figlet

import "testing"

func TestDebugA(t *testing.T) {
	font, err := loadFont("../../fonts", "standard")
	if err != nil {
		t.Fatal(err)
	}
	glyph, ok := font.GlyphForRune('A')
	if !ok {
		t.Fatal("missing glyph")
	}
	canvas := glyphToCanvas(glyph)
	trimmed, width := trimLeftCanvas(glyphToCanvas(glyph), glyph.Width, font.Hardblank)
	t.Logf("glyph width=%d lines=%q", glyph.Width, glyph.Lines)
	t.Logf("canvas=%q", canvas)
	t.Logf("trimmed width=%d trimmed=%q", width, trimmed)
}

func TestDebugEmbossH(t *testing.T) {
	font, err := loadFont("../../assets", "emboss")
	if err != nil {
		t.Fatal(err)
	}
	glyph, ok := font.GlyphForRune('H')
	if !ok {
		t.Fatal("missing H")
	}
	t.Logf("H width=%d lines=%q", glyph.Width, glyph.Lines)
}
